    .metrics-strip {
      background: #0d2148;
      display: flex;
      gap: 0;
      border-bottom: 3px solid #20b2aa;
    }
    .metric-card {
      flex: 1;
      padding: 28px 32px;
      border-right: 1px solid rgba(255,255,255,0.08);
      position: relative;
      transition: background 0.2s;
    }
    .metric-card:last-child { border-right: none; }
    .metric-card.risk-card { background: rgba(220,80,50,0.08); }
    .metric-value {
      font-size: 36px;
      font-weight: 800;
      line-height: 1;
      margin-bottom: 7px;
      letter-spacing: -1px;
    }
    .metric-card:not(.risk-card) .metric-value { color: #4fc3c3; }
    .metric-card.risk-card .metric-value { color: #e07050; }
    .metric-label {
      color: #c0d4e8;
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 1.2px;
      text-transform: uppercase;
      margin-bottom: 6px;
    }
    .metric-context {
      color: #7a95b0;
      font-size: 11.5px;
      line-height: 1.5;
    }
    .metric-badge {
      position: absolute;
      top: 14px; right: 14px;
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 1px;
      text-transform: uppercase;
      padding: 3px 8px;
      border-radius: 2px;
    }
    .badge-teal { background: rgba(32,178,170,0.18); color: #4fc3c3; }
    .badge-risk { background: rgba(220,80,50,0.18); color: #e07050; }

    /* ── BODY GRID ── */
    .poster-body {
      flex: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: auto auto auto;
      gap: 0;
      padding: 0;
    }

    /* ── SECTION PANELS ── */
    .section-panel {
      padding: 36px 40px;
      border-right: 1px solid #dde4ed;
      border-bottom: 1px solid #dde4ed;
    }
    .section-panel:nth-child(even) { border-right: none; }
    .section-panel.full-width {
      grid-column: 1 / -1;
      border-right: none;
    }

    .section-tag {
      display: inline-block;
      font-size: 9.5px;
      font-weight: 700;
      letter-spacing: 2px;
      text-transform: uppercase;
      padding: 3px 10px;
      border-radius: 2px;
      margin-bottom: 12px;
    }
    .tag-blue { background: #e8f0fb; color: #1a3a6e; }
    .tag-teal { background: #e0f5f4; color: #0d6e68; }
    .tag-amber { background: #fff4e0; color: #b06010; }
    .tag-red { background: #fdecea; color: #b03020; }

    .section-title {
      font-size: 17px;
      font-weight: 700;
      color: #0d2148;
      margin-bottom: 18px;
      line-height: 1.3;
      padding-bottom: 12px;
      border-bottom: 2px solid #e0e7f0;
    }

    /* ── OVERVIEW SECTION ── */
    .overview-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
      margin-top: 4px;
    }
    .overview-stat {
      background: linear-gradient(135deg, #f0f4fb, #e8f0f8);
      border-left: 3px solid #1a3a6e;
      border-radius: 4px;
      padding: 14px 16px;
    }
    .overview-stat .stat-num {
      font-size: 22px;
      font-weight: 800;
      color: #1a3a6e;
      line-height: 1;
    }
    .overview-stat .stat-label {
      font-size: 10.5px;
      color: #4a6080;
      margin-top: 4px;
      line-height: 1.4;
      font-weight: 500;
    }
    .overview-desc {
      font-size: 13px;
      color: #3a4e62;
      line-height: 1.72;
      grid-column: 1 / -1;
    }
    .model-pills {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-top: 14px;
      grid-column: 1 / -1;
    }
    .model-pill {
      background: #0d2148;
      color: #a8c4e0;
      font-size: 11px;
      font-weight: 600;
      padding: 5px 14px;
      border-radius: 20px;
      letter-spacing: 0.3px;
    }
    .model-pill.teal { background: #0d6e68; color: #c0f0ed; }

    /* ── APPLICATIONS ── */
    .app-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 12.5px;
    }
    .app-table th {
      text-align: left;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: #6a80a0;
      padding: 0 10px 10px 0;
      border-bottom: 1px solid #dde4ed;
    }
    .app-table td {
      padding: 10px 10px 10px 0;
      border-bottom: 1px solid #eef2f7;
      color: #2a3a4e;
      vertical-align: top;
      line-height: 1.5;
    }
    .app-table tr:last-child td { border-bottom: none; }
    .app-name {
      font-weight: 700;
      color: #0d2148;
      display: block;
      margin-bottom: 2px;
    }
    .maturity-dot {
      display: inline-block;
      width: 8px; height: 8px;
      border-radius: 50%;
      margin-right: 6px;
      vertical-align: middle;
    }
    .dot-pilot { background: #20b2aa; }
    .dot-research { background: #6690cc; }
    .dot-early { background: #88b84e; }
    .dot-active { background: #e8a030; }
    .dot-emerging { background: #b08050; }

    /* ── PERFORMANCE ── */
    .bench-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .bench-item {
      display: flex;
      align-items: center;
      gap: 14px;
    }
    .bench-model {
      font-size: 11.5px;
      font-weight: 700;
      color: #0d2148;
      width: 100px;
      flex-shrink: 0;
    }
    .bench-bar-wrap {
      flex: 1;
      position: relative;
    }
    .bench-bar-bg {
      height: 22px;
      background: #e8f0f8;
      border-radius: 3px;
      overflow: hidden;
    }
    .bench-bar-fill {
      height: 100%;
      border-radius: 3px;
      display: flex;
      align-items: center;
      padding: 0 10px;
      font-size: 11px;
      font-weight: 700;
      color: #fff;
    }
    .bar-gpt4    { background: linear-gradient(90deg, #1a3a6e, #2a6cc4); width: 92%; }
    .bar-medpalm { background: linear-gradient(90deg, #0d6e68, #20b2aa); width: 86.5%; }
    .bar-gpt35   { background: linear-gradient(90deg, #3a5070, #6690cc); width: 60%; }
    .bar-pass    { background: rgba(80,120,80,0.15); width: 60%; border: 1.5px dashed #80b080; }
    .bench-threshold {
      position: absolute;
      left: 60%;
      top: -18px;
      font-size: 9px;
      color: #80a080;
      font-weight: 600;
      letter-spacing: 0.5px;
      white-space: nowrap;
    }
    .bench-threshold::after {
      content: '';
      display: block;
      width: 1px;
      height: 26px;
      background: #80b080;
      margin: 2px auto 0;
      opacity: 0.5;
    }
    .bench-note {
      font-size: 11px;
      color: #7a95b0;
      margin-top: 16px;
      padding: 10px 14px;
      background: #f0f5fb;
      border-left: 3px solid #6690cc;
      border-radius: 3px;
      line-height: 1.6;
    }

    /* ── RISKS ── */
    .risk-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }
    .risk-item {
      background: #fff8f6;
      border: 1px solid #f0d8d0;
      border-left: 4px solid #c84030;
      border-radius: 4px;
      padding: 14px 16px;
    }
    .risk-item.moderate {
      background: #fffbf0;
      border: 1px solid #f0e0b0;
      border-left: 4px solid #d08010;
    }
    .risk-icon {
      font-size: 18px;
      margin-bottom: 6px;
    }
    .risk-label {
      font-size: 12px;
      font-weight: 700;
      color: #8a1010;
      margin-bottom: 4px;
    }
    .risk-item.moderate .risk-label { color: #7a4a00; }
    .risk-desc {
      font-size: 11.5px;
      color: #5a3a30;
      line-height: 1.55;
    }
    .risk-item.moderate .risk-desc { color: #5a4010; }
    .hallucination-callout {
      background: linear-gradient(135deg, #fdecea, #faf0ef);
      border: 1.5px solid #e08070;
      border-radius: 6px;
      padding: 16px 20px;
      margin-bottom: 16px;
      display: flex;
      align-items: center;
      gap: 16px;
    }
    .hallucination-pct {
      font-size: 42px;
      font-weight: 900;
      color: #c84030;
      line-height: 1;
      flex-shrink: 0;
    }
    .hallucination-text {
      font-size: 12.5px;
      color: #6a2010;
      line-height: 1.6;
    }
    .hallucination-text strong { color: #c84030; }

    /* ── FRAMEWORK ── */
    .framework-steps {
      display: flex;
      gap: 0;
      counter-reset: step;
      flex-wrap: nowrap;
    }
    .framework-step {
      flex: 1;
      position: relative;
      padding: 22px 20px 22px;
      background: #f5f8fd;
      border: 1px solid #dde4ed;
      border-right: none;
      text-align: center;
      counter-increment: step;
    }
    .framework-step:last-child {
      border-right: 1px solid #dde4ed;
      border-radius: 0 6px 6px 0;
    }
    .framework-step:first-child { border-radius: 6px 0 0 6px; }
    .framework-step::before {
      content: counter(step);
      display: block;
      width: 28px; height: 28px;
      background: #0d2148;
      color: #fff;
      border-radius: 50%;
      font-size: 12px;
      font-weight: 700;
      line-height: 28px;
      margin: 0 auto 10px;
    }
    .framework-step::after {
      content: '›';
      position: absolute;
      right: -14px;
      top: 50%;
      transform: translateY(-50%);
      font-size: 22px;
      color: #20b2aa;
      font-weight: 700;
      z-index: 2;
    }
    .framework-step:last-child::after { display: none; }
    .step-title {
      font-size: 11.5px;
      font-weight: 700;
      color: #0d2148;
      margin-bottom: 6px;
      line-height: 1.35;
    }
    .step-desc {
      font-size: 10.5px;
      color: #4a6080;
      line-height: 1.55;
    }
    .framework-note {
      background: linear-gradient(135deg, #0d2148, #1a3a6e);
      color: #a8c4e0;
      font-size: 12.5px;
      line-height: 1.7;
      padding: 18px 24px;
      border-radius: 6px;
      margin-top: 18px;
    }
    .framework-note strong { color: #4fc3c3; }

    /* ── FOOTER ── */
    .poster-footer {
      background: #0d2148;
      padding: 18px 64px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-top: 3px solid #20b2aa;
    }
    .footer-left {
      color: #6a90b8;
      font-size: 10.5px;
      line-height: 1.6;
    }
    .footer-right {
      color: #4fc3c3;
      font-size: 11px;
      font-weight: 600;
    }

    /* ── EXPORT BUTTON ── */
    #export-btn {
      position: fixed;
      bottom: 30px; right: 30px;
      background: #20b2aa;
      color: #fff;
      border: none;
      padding: 14px 28px;
      font-size: 14px;
      font-weight: 700;
      border-radius: 6px;
      cursor: pointer;
      box-shadow: 0 4px 20px rgba(0,0,0,0.35);
      z-index: 100;
      letter-spacing: 0.5px;
    }
    #export-btn:hover { background: #18a8a0; }
    #export-btn:disabled { background: #557070; cursor: not-allowed; }

    /* infographic containers */
    .infographic-panel {
      width: 100%;
      min-height: 320px;
    }
  </style>
</head>
