  <div class="poster-body">

    <!-- ── SECTION 1: Overview ── -->
    <div class="section-panel">
      <span class="section-tag tag-blue">Overview</span>
      <h2 class="section-title">What Are LLMs &amp; Why Do They Matter for Medicine?</h2>
      <div class="overview-grid">
