<script>
async function exportPNG() {
  const btn = document.getElementById('export-btn');
  btn.textContent = 'Generating…';
  btn.disabled = true;

  try {
    // Use html2canvas-style approach via canvas
    const poster = document.getElementById('poster');
    const width  = poster.offsetWidth;
    const height = poster.offsetHeight;

    // Use browser print / SVG serialisation approach
    const xml = new XMLSerializer().serializeToString(document.documentElement);

    // Attempt html2canvas if available, else SVG foreign object
    if (typeof html2canvas !== 'undefined') {
      const canvas = await html2canvas(poster, { scale: 2, useCORS: true, allowTaint: true });
      const link = document.createElement('a');
      link.download = 'LLMs-in-Medicine-poster.png';
      link.href = canvas.toDataURL('image/png');
      link.click();
    } else {
      // SVG foreignObject fallback
      const svgStr = `
        <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">
          <foreignObject width="100%" height="100%">
            <div xmlns="http://www.w3.org/1999/xhtml">${poster.outerHTML}</div>
          </foreignObject>
        </svg>`;
      const blob = new Blob([svgStr], { type: 'image/svg+xml' });
      const url  = URL.createObjectURL(blob);
      const img  = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width  = width * 2;
        canvas.height = height * 2;
        const ctx = canvas.getContext('2d');
        ctx.scale(2, 2);
        ctx.drawImage(img, 0, 0);
        URL.revokeObjectURL(url);
        const link = document.createElement('a');
        link.download = 'LLMs-in-Medicine-poster.png';
        link.href = canvas.toDataURL('image/png');
        link.click();
      };
      img.src = url;
    }
  } catch(e) {
    console.error(e);
    alert('Export error — try right-clicking the poster and saving as image, or use browser print → Save as PDF.');
  }

  btn.textContent = 'Export PNG';
  btn.disabled = false;
}
</script>

